let isDev=false;const DEV_KEY="dev";async function setDev(){await localStorage.setItem(DEV_KEY,"true")}async function unsetDev(){await localStorage.removeItem(DEV_KEY)}window.MODELS=null;async function initAstriaSdk(){isDev=Boolean(await readStoredText(DEV_KEY));window.BASE_URL=isDev?"http://localhost:3000/":"https://api.astria.ai/"}async function astriaFetch(e,t={}){return window.astriaOAuth.fetchApi(e,t)}const manifest=require("./manifest.json");const ASTRIA_WEB_URL="https://www.astria.ai";const ASTRIA_UTM={utm_source:"photoshop_plugin",utm_medium:"plugin"};function astriaWebUrl(e,t){const n=e.indexOf("#");const r=n===-1?"":e.slice(n);const a=n===-1?e:e.slice(0,n);const o=Object.entries({...ASTRIA_UTM,utm_campaign:t}).map(([s,c])=>`${s}=${encodeURIComponent(c)}`).join("&");const i=a.includes("?")?"&":"?";return`${ASTRIA_WEB_URL}${a}${i}${o}${r}`}function compareVersions(e,t){const n=e.split(".").map(Number);const r=t.split(".").map(Number);for(let a=0;a<Math.max(n.length,r.length);a++){const o=n[a]||0;const i=r[a]||0;if(o>i)return 1;if(o<i)return-1}return 0}function checkForUpdates(e){const t=manifest.version;["stable","beta"].forEach(n=>{const r=e?.[n];if(r&&compareVersions(r,t)>0){showUpdateNotification(n,r)}});document.getElementById("plugin-version").textContent=`v${t}`}function showUpdateNotification(e,t){const n=e==="stable"?"stable-update-notification":"beta-update-notification";const r=document.getElementById(n);if(r){r.setAttribute("data-version",t);r.classList.remove("hidden")}}const HEADERS={"Accept":"application/json"};function workspaceHeaders(e){const t=String(e||"");return t?{...HEADERS,"X-Workspace-Id":t}:HEADERS}function fetchWrapBase(e,t){return fetchWrap(BASE_URL+e,t)}AUTHORIZATION_ERROR="Authorization error";const GENERATION_CANCELLED="Generation cancelled";function fetchWrap(e,t){return astriaFetch(e,t).then(async n=>{if(n.ok){return n.json()}else{if(n.status===401){console.log("401");throw new Error(AUTHORIZATION_ERROR)}else if(n.status===500){throw new Error("Internal Server Error 500 - please try again in a few seconds")}else if(n.status===422){let a;try{a=await n.json()}catch(o){const i=await n.text().catch(()=>"");throw new Error(i||n.statusText||"Unprocessable Entity")}throw new Error(JSON.stringify(a))}let r;try{const a=await n.text();r=a||n.statusText||`HTTP ${n.status}`}catch(a){throw new Error(n.statusText||`HTTP ${n.status}`)}throw new Error(r)}})}async function createPromptByModelName(e,t,n={}){let r=window.MODELS[e];if(r.payload){const{text:o,...i}=r.payload;t={...t,...i};if(o){t.text=[t.text,o].filter(Boolean).join(" ")}}if(!t["num_images"]){t["num_images"]=1}if(t["input_images"]&&t["input_images"].length>0){return createTune(r,t,n)}delete t["input_images"];const a=`/tunes/${r.id}/prompts`;return createPrompt(a,t,{...n,timeout:n.timeout||r.timeout})}async function createTune(e,t,n={}){const r=e.id;let a=t["input_images"];delete t["input_images"];const o={name:"subject",title:"subject "+new Date().getTime(),model_type:"faceid",base_tune_id:r,images:a,...e.tune_payload||{}};const i=appendToFormData(o,"tune");const s=await fetchWrapBase("tunes",{method:"post",headers:workspaceHeaders(n.workspaceId),body:i});try{const c=await fetchWrapBase(`tunes/${s.id}/prompts`,{method:"post",headers:workspaceHeaders(n.workspaceId),body:appendToFormData(t,"prompt")});const u=await pollPrompt(c,{...n,timeout:n.timeout||e.timeout});u.tunes=[s];return u}catch(c){try{await deleteTune(s)}catch(u){console.warn("Failed to clean up the reference tune.",u)}throw c}}function appendToFormData(e,t,n){if(!n){n=new FormData}if(e instanceof Blob){n.append(t,e,"image."+e.type.split("/")[1]);return n}for(const[r,a]of Object.entries(e)){if(a instanceof Blob){n.append(`${t}[${r}]`,a,"image."+a.type.split("/")[1])}else if(typeof a==="object"){if(Array.isArray(a)){a.forEach((o,i)=>appendToFormData(o,`${t}[${r}][]`,n))}else{appendToFormData(a,`${t}[${r}]`,n)}}else{n.append(`${t}[${r}]`,a)}}return n}async function pollPrompt(e,t={}){const n=e.id;const r=t.timeout||180;const a=typeof t.shouldCancel==="function"?t.shouldCancel:()=>false;const o=typeof t.onProgress==="function"?t.onProgress:null;for(let i=0;i<r;i++){if(a()){await deletePromptAndTunes(e);throw new Error(GENERATION_CANCELLED)}const s=await fetchWrapBase(`prompts/${n}`,{method:"get",headers:HEADERS});if(s.trained_at){if(s.user_error||s.images.length===0){throw new Error(s.user_error||"Unknown error")}return s}if(o){try{o(s)}catch(c){console.warn("Could not report the generation progress.",c)}}await new Promise(c=>setTimeout(c,1e3))}await deletePromptAndTunes(e);throw new Error("Processing Timeout")}function jsonHeaders(){return{...HEADERS,"Content-Type":"application/json"}}function abortOption(e){return e?.signal?{signal:e.signal}:{}}async function createDirectUpload(e,t={}){return fetchWrapBase("api/direct_uploads",{method:"post",headers:jsonHeaders(),body:JSON.stringify({blob:e}),...abortOption(t)})}async function uploadDirectFile(e,t,n={}){if(!e?.url)throw new Error("The upload location is missing from the astria.ai reply.");const r=t instanceof Uint8Array?t.buffer.slice(t.byteOffset,t.byteOffset+t.byteLength):t;const a=await fetch(e.url,{method:"PUT",headers:e.headers||{},body:r,...abortOption(n)});if(!a.ok){const o=await a.text().catch(()=>"");const i=o.replace(/<[^>]*>/g," ").replace(/\s+/g," ").trim().slice(0,200);throw new Error(`Uploading the image failed (HTTP ${a.status})${i?`: ${i}`:""}`)}}async function createChatTicket(e={}){return fetchWrapBase("plugin/chat_ticket",{method:"post",headers:jsonHeaders(),body:JSON.stringify({workspace_id:e.workspaceId??null}),...abortOption(e)})}async function getUserBalance(e=HEADERS){const t=await fetchWrapBase("users",{method:"get",headers:e});return t}async function deleteTune(e){if(e?.title&&e.title.startsWith("subject")){await astriaFetch(BASE_URL+`tunes/${e.id}`,{method:"delete",headers:HEADERS})}}async function deletePromptAndTunes(e){await astriaFetch(BASE_URL+`prompts/${e.id}`,{method:"delete",headers:HEADERS});if(e.tunes&&e.tunes.length>0){for(const t of e.tunes){await deleteTune(t)}}}async function createPrompt(e,t,n={}){const r=appendToFormData(t,"prompt");let a;const o=await fetchWrapBase(e,{method:"post",headers:workspaceHeaders(n.workspaceId),body:r});return await pollPrompt(o,n)}
